/** Bindings and vars, as generated by `wrangler types` into worker-configuration.d.ts. */
export type Env = Cloudflare.Env

export const ttlDays = (env: Env) => Number(env.ROTATION_TTL_DAYS || 180)
export const createLimit = (env: Env) => Number(env.CREATE_LIMIT_PER_HOUR || 20)
export const webhookTimeoutMs = (env: Env) => Number(env.WEBHOOK_TIMEOUT_SECONDS || 5) * 1000
export const publicBaseUrl = (env: Env) => (env.PUBLIC_BASE_URL || 'http://localhost:8787').replace(/\/+$/, '')
